<div class="page-heading page-heading-compact"><div><p class="breadcrumbs"><a href="/admin/conversations">Conversations</a> <span>/</span> Detail</p><h1>Conversation</h1><p class="muted"><code><?= $escape($conversation->publicId) ?></code></p></div></div>
<section class="metadata-panel panel"><div><span>Chatbot</span><strong><?= $escape($chatbot?->name ?? '#' . $conversation->chatbotId) ?></strong></div><div><span>Traffic</span><strong><?= $conversation->isTest ? 'Test' : 'Production' ?></strong></div><div><span>Channel</span><strong><?= $escape($conversation->channel->value) ?></strong></div><div><span>Status</span><strong><?= $escape($conversation->status->value) ?></strong></div><div><span>Origin</span><code><?= $escape($conversation->normalizedOrigin ?? '—') ?></code></div><div><span>Provider tokens</span><strong><?= $escape(number_format($conversation->providerTokens)) ?></strong></div><div><span>Started</span><strong><?= $escape($formatDate($conversation->startedAt)) ?></strong></div><div><span>Last activity</span><strong><?= $escape($formatDate($conversation->lastActivityAt)) ?></strong></div></section>
<div class="section-heading"><h2>Transcript</h2><p>Content is rendered as text. Credentials, prompts, and raw provider responses are never shown.</p></div>
<?php if ($messages === []): ?><section class="empty-state compact-empty"><h3>No messages</h3></section><?php else: ?><div class="preview-transcript"><?php foreach ($messages as $message): ?><article class="preview-message preview-message-<?= $escape($message->role->value) ?>"><div class="preview-message-heading"><strong><?= $escape(ucfirst($message->role->value)) ?></strong><span><?= $escape($formatDate($message->createdAt)) ?> · <?= $escape($message->status->value) ?> · <code><?= $escape($message->requestId) ?></code></span></div><p><?= nl2br($escape($message->content ?? ($message->errorCode !== null ? 'Failed: ' . $message->errorCode : 'No content'))) ?></p><?php if ($message->citations !== null): ?><details><summary>Citations</summary><pre><?= $escape(json_encode($message->citations, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) ?></pre></details><?php endif; ?><small><?= $escape(number_format($message->providerTokens)) ?> provider tokens<?= $message->latencyMs !== null ? ' · ' . $escape($message->latencyMs) . ' ms' : '' ?></small></article><?php endforeach; ?></div><?php endif; ?>
